UPDATE `official_service_snapshot` SET `category` = (SELECT fix.`category` FROM `official_category_fix` AS fix WHERE fix.`service_id` = `official_service_snapshot`.`service_id`) WHERE `sync_run_id` = (SELECT `id` FROM `official_sync_run` WHERE `status` = 'succeeded' ORDER BY `completed_at` DESC LIMIT 1) AND EXISTS (SELECT 1 FROM `official_category_fix` AS fix WHERE fix.`service_id` = `official_service_snapshot`.`service_id` AND fix.`name` = `official_service_snapshot`.`name` AND fix.`from_category` = `official_service_snapshot`.`category`);
